#define WA(name) (0x7E0000u + (uint32_t)offsetof(union wram, name))
#define WAI(name, i) ((WA(name) & 0xFF0000u) | (uint16_t)(WA(name) + (i)))
#define RD8(name) rd8(WA(name))
#define RD16(name) rd16(WA(name))
#define WR8(name, v) wr8(WA(name), (v))
#define WR16(name, v) wr16(WA(name), (v))
#define RD8I(name, i) rd8(WAI(name, i))
#define RD16I(name, i) rd16(WAI(name, i))
#define WR8I(name, i, v) wr8(WAI(name, i), (v))
#define WR16I(name, i, v) wr16(WAI(name, i), (v))
/* An index carried on into the next bank, as long and absolute indexed
   addressing carry (from $7E:FF65 into $7F): the struct is one block. */
#define WAX(name, i) (WA(name) + (i))
#define RD8X(name, i) rd8(WAX(name, i))
#define RD16X(name, i) rd16(WAX(name, i))
#define WR8X(name, i, v) wr8(WAX(name, i), (v))
#define WR16X(name, i, v) wr16(WAX(name, i), (v))

